body:
Type: <b>Bug</b>

Chat (GPT 4.1) gave me the following:

function* generateCombinations(arr, size) {
 const n = arr.length;
 if (size > n || size <= 0) return;
 const indices = Array.from({ length: size }, (_, i) => i);
 while (true) {
 yield indices.map(i => arr[i]);
 // Find the rightmost index that can be incremented
 let i = size - 1;
 while (i >= 0 && indices[i] === i + n - size) i--;
 if (i < 0) break;
 indices[i]++;
 for (let j = i + 1; j < size; j++) {
 indices[j] = indices[j - 1] + 1;
 }
 }
}

When I used the "apply" button,
it processed the relevant file, highlighted stuff in red/green.
I hit accept.
It left an error.

VSC implemented the following:
function* generateCombinations(arr, size) {
 const n = arr.length;
 if (size > n || size <= 0) return;
 const indices = Array.from({ length: size }, (_, i) => i);
 while (true) {
 yield indices.map(i => arr[i]);
 // Find the rightmost index that can be incremented
 let i = size - 1;
 while (i >= 0 && indices[i] === i + n - size) i--;
 if i < 0) break;
 indices[i]++;
 for (let j = i + 1; j < size; j++) {
 indices[j] = indices[j - 1] + 1;
 }
 }
}

---

Note the last "if" condition - it's missing the opening bracket!
(There in the chat code, not there when applied in the IDE)

